<script setup lang="ts">
import { computed, ref } from 'vue';
import { onLoad } from '@dcloudio/uni-app';
import { getJob } from '../../services/api';
const query = ref<{ platform?: string; id?: string }>({}); const platform = computed(() => ({ doubao: '豆包', douyin: '抖音', xhs: '小红书', qianwen: '千问', wechat_channels: '微信视频号', jimeng: '即梦', kuaishou: '快手' }[query.value.platform || ''] || '素材'));
const mediaCount = ref(0); const isSuccess = ref(false); const media = ref<{ type: string; proxyUrl: string } | null>(null);
onLoad(async (options) => { const received = (options || {}) as { platform?: string; id?: string }; query.value = received; if (!received.id) return; try { const job = await getJob(received.id); mediaCount.value = job.media.length; isSuccess.value = job.status === 'SUCCESS'; media.value = job.media[0] || null; } catch { uni.showToast({ title: '无法读取解析结果', icon: 'none' }); } });
function save() { if (!media.value) return; const token = uni.getStorageSync('access_token'); uni.downloadFile({ url: media.value.proxyUrl, header: { Authorization: `Bearer ${token}` }, success: ({ tempFilePath }) => { if (media.value?.type === 'IMAGE') uni.saveImageToPhotosAlbum({ filePath: tempFilePath, success: () => uni.showToast({ title: '已保存到相册' }) }); else uni.saveVideoToPhotosAlbum({ filePath: tempFilePath, success: () => uni.showToast({ title: '已保存到相册' }) }); }, fail: () => uni.showToast({ title: '下载失败，请重试', icon: 'none' }) }); }
function copy() { if (media.value) uni.setClipboardData({ data: media.value.proxyUrl }); }
</script>
<template><view class="page"><view class="status"><text class="tick">{{ isSuccess ? '✓' : '…' }}</text><text>{{ isSuccess ? '提取成功' : '正在读取结果' }}</text><text class="detail">{{ platform }} · {{ mediaCount || 1 }} 个素材</text></view><view class="preview"><view class="play">▶</view><text>高清素材预览</text></view><view class="facts"><view><text>类型</text><b>视频</b></view><view><text>素材数量</text><b>{{ mediaCount || 1 }}</b></view><view><text>状态</text><b>{{ isSuccess ? '成功' : '处理中' }}</b></view></view><button class="save" :disabled="!isSuccess" @click="save">保存到相册</button><button class="copy" :disabled="!isSuccess" @click="copy">复制链接</button><text class="note">解析成功后已扣除 1 点；保存失败不会再次扣点</text></view></template>
<style scoped>.page{min-height:100vh;padding:50rpx 36rpx;box-sizing:border-box;background:#f7f8fb}.status{display:flex;flex-direction:column;align-items:center;font-size:38rpx;font-weight:800}.tick{display:grid;place-items:center;width:88rpx;height:88rpx;background:#e5faef;color:#24a160;border-radius:50%;margin-bottom:18rpx}.detail,.note{font-size:24rpx;font-weight:400;color:#807a8c;margin-top:10rpx}.preview{height:460rpx;margin-top:52rpx;border-radius:28rpx;background:#2c263b;display:flex;flex-direction:column;justify-content:center;align-items:center;color:#fff;font-size:24rpx}.play{width:92rpx;height:92rpx;border-radius:50%;background:#fff;color:#6f3ff5;display:grid;place-items:center;font-size:35rpx;margin-bottom:22rpx}.facts{display:flex;background:#fff;border-radius:24rpx;margin:28rpx 0;padding:28rpx 10rpx;justify-content:space-around}.facts view{display:flex;flex-direction:column;gap:10rpx;font-size:22rpx;color:#8a8495}.facts b{font-size:24rpx;color:#342f3d}.save,.copy{border-radius:18rpx;height:94rpx;line-height:94rpx;font-weight:700}.save{background:#6f3ff5;color:#fff}.copy{margin-top:18rpx;background:#ede9f7;color:#5b3dc0}.note{display:block;text-align:center;line-height:1.5;margin:30rpx 25rpx}</style>
